<?php if ($services === []): ?><div class="empty">Nog geen diensten. <a href="<?= e(url('/oplossingen/webhosting')) ?>">Bekijk ons aanbod</a>.</div><?php else: ?>
<div class="table-wrap"><table class="table"><thead><tr><th>Dienst</th><th>Prijs</th><th>Volgende factuur</th><th>Status</th></tr></thead><tbody>
<?php foreach ($services as $s): ?><tr><td><a href="<?= e(url('/klant/diensten/' . $s->id())) ?>"><strong><?= dienst_naam($s) !== (string) $s->Naam ? icon('globe', 'icon icon-sm') . ' ' : '' ?><?= e(dienst_naam($s)) ?></strong></a><div class="small muted"><?= e($s->Nummer) ?></div></td><td class="nowrap"><?= e(money((int) $s->Prijs)) ?> <span class="small muted"><?= e(period_label((string) $s->Periode)) ?></span></td><td><?= e(nl_date($s->VolgendeFactuur)) ?></td><td><?= badge((string) $s->Status, \App\Models\Service::STATUSES[$s->Status] ?? $s->Status) ?></td></tr><?php endforeach; ?>
</tbody></table></div><?php endif; ?>
